MOD = 998244353
n = int(input())
p = list(map(lambda x: int(x) - 1, input().split()))
s = list(input())

valid_configurations = 0

for config in range(1 << n):
    sp = [True for _ in range(n)]
    valid = True
    for i in p:
        left = (i - 1 + n) % n
        right = (i + 1) % n
        if (config & (1 << i)) > 0:  # Right hand
            if sp[right]:
                sp[right] = False
            elif s[i] == '?':
                if sp[left]:
                    sp[left] = False
                else:
                    valid = False
                    break
            else:
                valid = False
                break
        else:  # Left hand
            if sp[left]:
                sp[left] = False
            elif s[i] == '?':
                if sp[right]:
                    sp[right] = False
                else:
                    valid = False
                    break
            else:
                valid = False
                break
    if valid:
        valid_configurations += 1
        valid_configurations %= MOD

print(valid_configurations)
